# Define a dataclass to represent a backup job
@dataclass
class BackupJob:
    id: int
    timestamp: datetime
    filename: str
    status: str

# Define a dataclass to represent a report entry
@dataclass
class ReportEntry:
    date: datetime
    backups: List[BackupJob]

# Define the backup report dashboard
class BackupReport:
    def __init__(self):
        self.entries: List[ReportEntry] = []

    def add_backup(self, job: BackupJob):
        entry = ReportEntry(self._get_current_date(), [job])
        self.entries.append(entry)

    def _get_current_date(self) -> datetime:
        return datetime.now()

    def add_restore(self, job: BackupJob):
        for entry in self.entries:
            if entry.date == self._get_current_date():
                entry.backups.append(job)
                return
        entry = ReportEntry(self._get_current_date(), [job])
        self.entries.append(entry)

    def get_summary(self) -> str:
        report = ""
        for entry in self.entries:
            report += f"Date: {entry.date}\n"
            for job in entry.backups:
                report += f"  {job.filename} ({job.status})\n"
        return report

class BackupSystem:
    def __init__(self):
        self.dashboard = BackupReport()

    def backup(self, filename: str):
        # Simulate a backup
