                    if urlparse(current_url).netloc!= urlparse(link_url).netloc:
                        urls_to_visit.append(link_url)
                else:
                    if urlparse(url).netloc:
                        link_url = f"{urlparse(url).netloc}{link_url}"

                    urls_to_visit.append(link_url)
