class Synchronizer:
    def __init__(self, src, dest):
        self.src = Path(src)
        self.dest = Path(dest)

    def sync(self):
        if not self.src.exists():
            raise ValueError(f"Source directory '{self.src}' does not exist.")
        if not self.dest.exists():
            # Create destination directory if it does not exist
            self.dest.mkdir(parents=True, exist_ok=True)

        for root, dirs, files in os.walk(self.src):
            relative_path = os.path.relpath(root, self.src)
            dest_path = self.dest / relative_path

            if not dest_path.exists():
                # Create destination directory if it does not exist
                dest_path.mkdir(parents=True, exist_ok=True)

            for file in files:
                src_file = self.src / relative_path / file
                dest_file = dest_path / file

                if not dest_file.exists():
                    shutil.copy2(src_file, dest_file)

                elif src_file.stat().st_mtime > dest_file.stat().st_mtime:
                    # Overwrite the updated file in the destination directory
                    shutil.copy2(src_file, dest_file)

                elif src_file.stat().st_mtime < dest_file.stat().st_mtime:
                    # Remove the file in the destination directory
                    dest_file.unlink()
                    shutil.copy2(src_file, dest_file)

    def incremental_sync(self):
        # Only sync files that have changed since the last sync
        for root, dirs, files in os.walk(self.src):
            relative_path = os.path.relpath(root, self.src)
            dest_path = self.dest / relative_path

            if not dest_path.exists():
                # Create destination directory if it does not exist
                dest_path.mkdir(parents=True, exist_ok=True)

            for file in files:
                src_file = self.src / relative_path / file
                dest_file = dest_path / file

                if dest_file.exists():
                    if src_file.stat().st_mtime > dest_file.stat().st_mtime:
                        # Overwrite the updated file in the destination directory
                        shutil.copy2(src_file, dest_file)
                else:
