import requests

class RedirectTracer:
    def __init__(self, url):
        self.url = url
        self.redirect_chain = []

    def follow_redirects(self):
        while True:
            try:
                response = requests.head(self.url, allow_redirects=True)
                if response.history:
                    self.url = response.url
                    self.redirect_chain.append((response.url, response.status_code))
                else:
                    break
            except requests.Timeout as e:
                print(f"Timeout Error: {e}")
            except requests.RequestException as e:
                print(f"Request Error: {e}")

        return self.redirect_chain

    def get_redirect_chain(self):
        redirects = self.follow_redirects()
        return '\n'.join([f'{url} ({status_code})' for url, status_code in redirects][::-1])


def main():
    url = input("Enter URL for redirect trace: ")
    tracer = RedirectTracer(url)
    print(tracer.get_redirect_chain())


if __name__ == "__main__":
