                    self._copy_dir(sftp, local_path, remote_path)
                elif os.path.isfile(local_path):
                    sftp.put(local_path, remote_path)
                    os.utime(remote_path, None, (os.path.getatime(local_path), os.path.getmtime(local_path)))
            except Exception as e:
