            remote_path = os.path.join(self.remote_dir, remote_file)
            if sftp.isdir(remote_path):
                if not os.path.exists(local_path):
                    sftp.mkdir(local_path)
                self._copy_dir(sftp, remote_path, local_path)
            elif sftp.isfile(remote_path):
                local_dir = os.path.dirname(local_path)
                if not os.path.exists(local_dir):
                    os.makedirs(local_dir)
                sftp.get(remote_path, local_path)
                os.utime(local_path, None, (os.path.getatime(remote_path), os.path.getmtime(remote_path)))
        sftp.close()

