class WebLogAnalyzer:
    def __init__(self, url, max_workers=10):
        self.url = url
        self.max_workers = max_workers
        self.dead_links = []

    def is_valid_url(self, url):
        try:
            result = urlparse(url)
            return all([result.scheme, result.netloc])
        except ValueError:
            return False

    def fetch_data(self, url):
        try:
            response = requests.get(url)
            return response.status_code == 200
        except requests.exceptions.RequestException:
            return False

    def scan(self):
        with ThreadPoolExecutor(max_workers=self.max_workers) as executor:
            queue = Queue()
            queue.put(self.url)
            while not queue.empty():
                url = queue.get()
                executor.submit(self.scan_url, url)
                sleep(0.1)

    def scan_url(self, url):
        if self.is_valid_url(url):
            response = requests.head(url, allow_redirects=False)
            if response.status_code == 404:
                self.dead_links.append(url)
            if response.status_code == 200 and response.headers['Location']:
                new_url = urljoin(url, response.headers['Location'])
                if self.is_valid_url(new_url):
                    queue.put(new_url)
                else:
                    logging.info(f"Ignoring invalid url: {new_url}")

if __name__ == "__main__":
    analyzer = WebLogAnalyzer("https://example.com")
    analyzer.scan()
    print("Dead links:")
    for link in analyzer.dead_links:
        print(link)
