            local_file_path = os.path.join(self.local_dir, local_file)
            remote_file_path = os.path.join(self.remote_dir, local_file)
            sftp.put(local_file_path, remote_file_path)
            sftp.close()
            print(f"Sent {local_file} to {self.hostname}")
        except Exception as e:
            print(f"Failed to send {local_file} to {self.hostname}: {str(e)}")

