            sftp = self.client.open_sftp()
            remote_file_path = os.path.join(self.remote_dir, remote_file)
            local_file_path = os.path.join(self.local_dir, remote_file)
            sftp.get(remote_file_path, local_file_path)
            sftp.close()
            print(f"Received {remote_file} from {self.hostname}")
        except Exception as e:
            print(f"Failed to receive {remote_file} from {self.hostname}: {str(e)}")

    def disconnect(self):
        self.client.close()

