import requests
import json

def get_data(url, expected_schema):
    """
    Fetches data from a RESTful API, parses the response as JSON, and verifies the schema.

    Args:
    url (str): The URL of the RESTful API.
    expected_schema (dict): The expected structure of the JSON response.

    Returns:
    The JSON data if the response matches the expected schema, otherwise raises an exception.
    """
    try:
        # Send a GET request to the API
        response = requests.get(url)
        response.raise_for_status()
    except requests.RequestException as e:
        raise Exception(f"Failed to fetch data: {str(e)}")

    try:
        # Parse the response as JSON
        data = json.loads(response.text)
    except json.JSONDecodeError as e:
        raise Exception(f"Failed to parse response as JSON: {str(e)}")

    # Verify the schema
    def is_valid_schema(obj, schema):
        for key, value in schema.items():
            if isinstance(value, dict):
                if key not in obj or not is_valid_schema(obj[key], value):
                    return False
            elif isinstance(value, list):
                if key not in obj or not all(is_valid_schema(item, value[0]) for item in obj[key]):
                    return False
            elif obj.get(key)!= value:
                return False
        return True

    if not is_valid_schema(data, expected_schema):
        raise Exception("The response does not match the expected schema")

    return data
