            with open(filename, 'rb') as file:
                return hashlib.md5(file.read()).hexdigest()
        except:
            return None

    def deploy(self):
        if not self.checkout_code():
            print("Failed to checkout code")
            sys.exit(1)
        commit_hash = self.get_commit_hash()
        if not commit_hash:
            print("Failed to get commit hash")
            sys.exit(1)
        file_hash = self.get_file_hash('main.py')
        if not file_hash:
            print("Failed to get file hash")
            sys.exit(1)
        try:
            subprocess.run(['git', 'add', '.'], cwd=self.deploy_dir)
            subprocess.run(['git', 'commit', '-m', 'deploy: {} ({})'.format(commit_hash, file_hash)], cwd=self.deploy_dir)
            subprocess.run(['git', 'push', '-u', 'origin', self.branch], cwd=self.deploy_dir)
            return True
        except:
            return False

